// De import registreert de elementen.
import {
    VlMap,
    VlMapBaseLayerGRBGray,
    VlMapFeaturesLayer,
    VlMapLayerCircleStyle,
    VlMapLayerStyle,
    VlMapLegend,
} from '@domg-wc/map';

// De features als GeoJSON-object in Lambert 72: twee punten en een polygoon, elk met een styleId.
document.querySelector('vl-map-features-layer').features = {
    type: 'FeatureCollection',
    features: [
        {
            type: 'Feature',
            geometry: { type: 'Point', coordinates: [153055, 203908] },
            properties: { styleId: 'style-1' },
        },
        {
            type: 'Feature',
            geometry: { type: 'Point', coordinates: [141000, 200908] },
            properties: { styleId: 'style-2' },
        },
        {
            type: 'Feature',
            geometry: {
                type: 'Polygon',
                coordinates: [
                    [
                        [147055, 197908],
                        [157055, 197908],
                        [157055, 187908],
                        [147055, 187908],
                        [147055, 197908],
                    ],
                ],
            },
            properties: { styleId: 'style-3' },
        },
    ],
};

// De TypeScript-code van de pagina (linkStylesToFeatures), als JavaScript: elke stijl geldt enkel voor de features
// met haar styleId. De handler hangt aan DOMContentLoaded: registreer hem voor dat event, bv. in een module-script.
document.addEventListener('DOMContentLoaded', async () => {
    const map = document.getElementById('map');
    await map?.ready;
    document.querySelector('#style-1').appliesTo = (feature) => feature.get('styleId') === 'style-1';
    document.querySelector('#style-2').appliesTo = (feature) => feature.get('styleId') === 'style-2';
    document.querySelector('#style-3').appliesTo = (feature) => feature.get('styleId') === 'style-3';
});

map-legend--map-legend-multiple-features.js:
// De import registreert de elementen.
import {
    VlMap,
    VlMapActionControls,
    VlMapBaseLayerGRBGray,
    VlMapFeaturesLayer,
    VlMapLayerCircleStyle,
    VlMapLayerStyle,
    VlMapLegend,
    VlMapMeasureAction,
    VlMapMeasureControl,
} from '@domg-wc/map';

// Elke laag krijgt haar punten als GeoJSON-object in Lambert 72. featureCharacter is de tekst in het punt
// (text-feature-attribute-name van de stijl).
const point = (coordinates, featureCharacter, zIndex) => ({
    type: 'Feature',
    geometry: { type: 'Point', coordinates },
    properties: { featureCharacter, zIndex },
});
const layer = (name) => document.querySelector(`vl-map-features-layer[name="${name}"]`);

layer('Openbare onderzoeken').features = {
    type: 'FeatureCollection',
    features: [
        point([147055, 197908], 'O', '1'),
        point([147075, 197908], 'O', '2'),
        point([147095, 197908], 'O', '3'),
        point([147105, 197908], 'O', '4'),
        point([147106, 197908], 'O', '5'),
    ],
};
layer('Beslissingen').features = { type: 'FeatureCollection', features: [point([141000, 200908], 'B', '5')] };
layer('Wateroppervlaktes').features = { type: 'FeatureCollection', features: [point([153055, 203908], 'W', '5')] };

